CREATE TABLE IF NOT EXISTS public.customers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,legal_entity_id UUID NOT NULL REFERENCES public.legal_entities(id) ON DELETE CASCADE,customer_code TEXT NOT NULL,name_ar TEXT NOT NULL,name_en TEXT,tax_number TEXT,email TEXT,phone TEXT,payment_terms_days INTEGER NOT NULL DEFAULT 30 CHECK(payment_terms_days>=0),currency_code CHAR(3) NOT NULL DEFAULT 'IQD' REFERENCES public.currencies(code),is_active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(legal_entity_id,customer_code));
ALTER TABLE public.accounts_receivable ADD COLUMN IF NOT EXISTS legal_entity_id UUID REFERENCES public.legal_entities(id) ON DELETE CASCADE,ADD COLUMN IF NOT EXISTS customer_id UUID REFERENCES public.customers(id) ON DELETE RESTRICT,ADD COLUMN IF NOT EXISTS invoice_date DATE,ADD COLUMN IF NOT EXISTS currency_code CHAR(3) REFERENCES public.currencies(code),ADD COLUMN IF NOT EXISTS exchange_rate NUMERIC(24,10) NOT NULL DEFAULT 1 CHECK(exchange_rate>0),ADD COLUMN IF NOT EXISTS amount_received NUMERIC(15,2) NOT NULL DEFAULT 0 CHECK(amount_received>=0),ADD COLUMN IF NOT EXISTS approved_at TIMESTAMPTZ,ADD COLUMN IF NOT EXISTS approved_by UUID REFERENCES public.profiles(id),ADD COLUMN IF NOT EXISTS posted_journal_entry_id UUID REFERENCES public.journal_entries(id),ADD COLUMN IF NOT EXISTS notes TEXT;
UPDATE public.accounts_receivable ar SET legal_entity_id=e.id,currency_code='IQD',invoice_date=COALESCE(ar.created_at::DATE,CURRENT_DATE) FROM public.legal_entities e WHERE e.tenant_id=ar.tenant_id AND e.code='DEFAULT' AND ar.legal_entity_id IS NULL;
ALTER TABLE public.accounts_receivable ALTER COLUMN legal_entity_id SET NOT NULL; ALTER TABLE public.accounts_receivable ALTER COLUMN currency_code SET NOT NULL; ALTER TABLE public.accounts_receivable ALTER COLUMN invoice_date SET NOT NULL; ALTER TABLE public.accounts_receivable DROP CONSTRAINT IF EXISTS accounts_receivable_status_check; ALTER TABLE public.accounts_receivable ADD CONSTRAINT accounts_receivable_status_check CHECK(status IN('draft','submitted','approved','partially_received','paid','overdue','voided'));
ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;ALTER TABLE public.accounts_receivable ENABLE ROW LEVEL SECURITY;CREATE POLICY finance_customers_access ON public.customers FOR ALL TO authenticated USING(public.current_user_can_access_legal_entity(legal_entity_id)) WITH CHECK(public.current_user_can_manage_legal_entity(legal_entity_id));CREATE POLICY finance_ar_access ON public.accounts_receivable FOR ALL TO authenticated USING(public.current_user_can_access_legal_entity(legal_entity_id)) WITH CHECK(public.current_user_can_manage_legal_entity(legal_entity_id));
